/* Behavior only: the actual header and footer are static HTML generated by scripts/sync-site-shell.mjs. */
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[data-site-header]').forEach((header) => {
    const toggle = header.querySelector('.al-menu-toggle');
    const menu = header.querySelector('.al-mobile-menu');
    const dropdowns = [...header.querySelectorAll('.al-dropdown')];
    const closeDropdowns = () => dropdowns.forEach((item) => {
      item.classList.remove('open');
      item.querySelector('.al-dropdown-trigger')?.setAttribute('aria-expanded', 'false');
    });
    dropdowns.forEach((item) => {
      const trigger = item.querySelector('.al-dropdown-trigger');
      trigger?.addEventListener('click', () => {
        const open = !item.classList.contains('open');
        closeDropdowns();
        item.classList.toggle('open', open);
        trigger.setAttribute('aria-expanded', String(open));
      });
    });
    const closeMobile = () => {
      if (!toggle || !menu) return;
      menu.hidden = true;
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'Open navigation menu');
    };
    toggle?.addEventListener('click', () => {
      const open = toggle.getAttribute('aria-expanded') !== 'true';
      toggle.setAttribute('aria-expanded', String(open));
      toggle.setAttribute('aria-label', open ? 'Close navigation menu' : 'Open navigation menu');
      menu.hidden = !open;
      if (open) menu.querySelector('a')?.focus({ preventScroll: true });
    });
    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        closeDropdowns();
        closeMobile();
        toggle?.focus({ preventScroll: true });
      }
    });
    document.addEventListener('click', (event) => {
      if (!header.contains(event.target)) closeDropdowns();
    });
    menu?.querySelectorAll('a').forEach((link) => link.addEventListener('click', closeMobile));
  });
  document.querySelectorAll('[data-year]').forEach((node) => { node.textContent = String(new Date().getFullYear()); });
});